const CDN_HOSTS = ['cdn.jsdelivr.net', 'fonts.googleapis.com', 'fonts.gstatic.com'];

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(SHELL_CACHE).then((cache) => cache.addAll(PRECACHE.map((u) => new Request(u, { cache: 'reload' })))));
  // No skipWaiting() here on purpose — the page decides when it is safe.
});

self.addEventListener('message', (event) => {
  if (event.data?.type === 'SKIP_WAITING') self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k.startsWith('mentora-') && k !== SHELL_CACHE && k !== RUNTIME_CACHE).map((k) => caches.delete(k)));
    await self.clients.claim();
  })());
});

const isPrivate = (url) => url.hostname.endsWith('supabase.co') || url.hostname.endsWith('supabase.in') || url.pathname.includes('/auth/') || url.pathname.includes('/rest/') || url.pathname.includes('/storage/');

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;                 // payments, forms, uploads → always network
  const url = new URL(req.url);
  if (isPrivate(url)) return;                        // never touch private API traffic
  if (url.searchParams.has('nocache')) return;

  if (req.mode === 'navigate') {
    event.respondWith((async () => {
      try {
        const fresh = await fetch(req);
        if (fresh.ok && url.origin === location.origin) {
          const cache = await caches.open(RUNTIME_CACHE);
          cache.put(url.pathname, fresh.clone());   // cache public page shells only (no query string)
        }
        return fresh;
      } catch {
        return (await caches.match(url.pathname, { ignoreSearch: true })) ||
               (await caches.match(req, { ignoreSearch: true })) ||
               (await caches.match(new URL('offline.html', self.registration.scope).pathname)) ||
               new Response('Offline', { status: 503, headers: { 'Content-Type': 'text/plain' } });
      }
    })());
    return;
  }

  if (url.origin === location.origin || CDN_HOSTS.includes(url.hostname)) {
    event.respondWith((async () => {
      const cached = await caches.match(req, { ignoreSearch: url.origin === location.origin });
      if (cached) return cached;
      try {
        const res = await fetch(req);
        if (res.ok || res.type === 'opaque') (await caches.open(RUNTIME_CACHE)).put(req, res.clone());
        return res;
      } catch {
        return new Response('', { status: 504 });
      }
    })());
  }
});
